require_once __DIR__.'/../includes/functions.php';require_login();require_once __DIR__.'/../config/database.php';$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT * FROM projects WHERE project_id=? AND is_active=1');$st->execute([$id]);$project=$st->fetch();if(!$project){flash('Project not found.','error');redirect('projects/index.php');}$st=$pdo->prepare('SELECT s.skill_id,s.skill_name,ps.target_level FROM project_skills ps JOIN skills s ON s.skill_id=ps.skill_id WHERE ps.project_id=?');$st->execute([$id]);$skills=$st->fetchAll();$st=$pdo->prepare('SELECT saved_project_id FROM saved_projects WHERE user_id=? AND project_id=?');$st->execute([(int)current_user()['user_id'],$id]);$saved=(bool)$st->fetchColumn();$pageTitle=$project['title'];$active='projects';include __DIR__.'/../includes/header.php';?>
